x={"A": "Splitting and reassembling messages is complex custom code, and SQS standard queues do not guarantee ordering of the parts.",
   "C": "SNS has a similar maximum message size and does not provide queue-based buffering by itself.",
   "D": "An EBS volume is attached to one instance, so worker services cannot read the payloads."},
